      "varType": "string",
      "category": "vaInputs",
      "nodeId": "8132ff1c06db49f1945f1e09cafbddf2",
      "isHidden": true,
      "description": "Identify the badge type, intelligently recognizes synonymous terms and infers user intent.\n\n** Badge Types with Synonyms **\n     -Temporary Badge(synonyms: Visitor Badge, Guest Badge, Contractor Badge, Short-Term Badge, Day Pass)\n     -Mobile Credential(synonyms: Digital Badge, Virtual Badge, Mobile Pass, Phone Credential, NFC Badge, App Credential)\n     -Permanent Badge(synonyms: Employee Badge, Staff Badge, Standard Badge, Long-Term Badge, Regular Badge, Access Card)"
    },
    "a20b234c47bb45eab13b0e04f666d4a1": {
      "id": "a20b234c47bb45eab13b0e04f666d4a1",
      "name": "topic_input_badge_action",
      "label": "Topic_input_badge_action",
      "varType": "string",
      "category": "vaInputs",
      "nodeId": "6ab93d3ed0984386956f249f29894f65",
      "isHidden": true,
      "description": "Identify the target user for badge action, intelligently recognizes synonymous terms and infers user intent.\n** Badge Actions with Synonyms **\n    -Assign (synonyms: Add, Issue, New)\n    -Update (synonyms: Modify, Edit, Change)\n    -Replace (synonyms: Swap, Reissue)\n    -Activate (synonyms: Enable, Turn On)\n    -Deactivate (synonyms: Disable, Turn Off, Suspend)\n    -Remove (synonyms: Delete, Revoke, Withdraw)\n    -Return (synonyms: Surrender, Hand Back)"
    },
